const input = $input.first().json;

const timestamp = new Date()
  .toISOString()
  .replace(/[:.]/g, '-');

const random = Math.random()
  .toString(36)
  .substring(2, 8);

const runId = `${timestamp}-${random}`;

return [{
  json: {
    ...input,
    run_id: runId,
    iteration: 1,
    run_dir: `${input.workspace}/runs/${runId}`
  }
}];

const response = $input.first().json;
const config = $('Create Run ID').first().json;

let content = response?.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('Task Breaker returned no message content');
}

content = String(content).trim();
content = content.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
content = content.replace(/```json/gi, '').replace(/```/g, '').trim();

const firstBrace = content.indexOf('{');
const lastBrace = content.lastIndexOf('}');

if (firstBrace === -1 || lastBrace === -1 || lastBrace <= firstBrace) {
  throw new Error(`No JSON object found in Task Breaker response: ${content}`);
}

const jsonText = content.substring(firstBrace, lastBrace + 1);

let plan;
try {
  plan = JSON.parse(jsonText);
} catch (e) {
  throw new Error(`Task Breaker JSON parsing failed: ${e.message}\n\nReceived:\n${jsonText}`);
}

if (!Array.isArray(plan.tasks)) {
  throw new Error('Task Breaker output has no tasks array');
}

if (plan.tasks.length < 1) {
  throw new Error('Task Breaker returned zero tasks');
}

if (plan.tasks.length > config.max_subtasks) {
  throw new Error(`Task Breaker returned ${plan.tasks.length} tasks; maximum is ${config.max_subtasks}`);
}

const seen = {};

for (let i = 0; i < plan.tasks.length; i++) {
  const task = plan.tasks[i];

  if (!task.id) {
    task.id = `T${String(i + 1).padStart(2, '0')}`;
  }

  if (seen[task.id]) {
    throw new Error(`Duplicate task ID: ${task.id}`);
  }

  seen[task.id] = true;
}

return [{
  json: {
    ...config,
    plan
  }
}];

const data = $input.first().json;

return [{
  json: {
    ...data,
    plan_json_b64: Buffer.from(JSON.stringify(data.plan, null, 2)).toString('base64')
  }
}];

const data = $('Parse Plan').first().json;

return data.plan.tasks.map(task => ({
  json: {
    run_id: data.run_id,
    run_dir: data.run_dir,
    workspace: data.workspace,
    major_task: data.major_task,
    verifier_model: data.verifier_model,
    litellm_base_url: data.litellm_base_url,
    iteration: data.iteration,
    task,
    task_json_b64: Buffer.from(JSON.stringify(task, null, 2)).toString('base64')
  }
}));

const taskData = $('Loop Over Tasks').first().json;

return [{
  json: taskData
}];

const taskData = $('Restore Current Task').first().json;
const commandResult = $input.first().json;

let memory = {
  reviews: []
};

try {
  memory = JSON.parse(commandResult.stdout || '{"reviews":[]}');
} catch (e) {
  memory = {
    reviews: []
  };
}

return [{
  json: {
    ...taskData,
    verifier_memory: memory
  }
}];

const response = $input.first().json;
const source = $('Combine Task + Memory').first().json;

let content = response?.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('Verifier returned no message content');
}

content = String(content).trim();
content = content.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
content = content.replace(/```json/gi, '').replace(/```/g, '').trim();

const firstBrace = content.indexOf('{');
const lastBrace = content.lastIndexOf('}');

if (firstBrace === -1 || lastBrace === -1 || lastBrace <= firstBrace) {
  throw new Error(`No JSON object found in Verifier response: ${content}`);
}

const jsonText = content.substring(firstBrace, lastBrace + 1);

let review;
try {
  review = JSON.parse(jsonText);
} catch (e) {
  throw new Error(`Verifier JSON parsing failed: ${e.message}\n\nReceived:\n${jsonText}`);
}

if (!['PASS', 'FAIL'].includes(review.verdict)) {
  throw new Error('Verifier verdict must be PASS or FAIL');
}

if (typeof review.score !== 'number') {
  throw new Error('Verifier score must be numeric');
}

review.task_id = source.task.id;

const memoryEntry = {
  run_id: source.run_id,
  iteration: source.iteration,
  task_id: source.task.id,
  verdict: review.verdict,
  score: review.score,
  problems: review.problems || [],
  required_changes: review.required_changes || []
};

return [{
  json: {
    ...source,
    review,
    review_json_b64: Buffer.from(JSON.stringify(review, null, 2)).toString('base64'),
    memory_entry_b64: Buffer.from(JSON.stringify(memoryEntry)).toString('base64')
  }
}];

const reviewData = $('Parse Review').first().json;

return [{
  json: reviewData
}];

const reviewData = $('Restore Review Data').first().json;

return [{
  json: reviewData
}];

const run = $('Parse Plan').first().json;
const items = $input.all();

const reviews = items
  .map(item => item.json.review)
  .filter(Boolean);

const failures = reviews.filter(review =>
  review.verdict === 'FAIL' || review.score < 8
);

return [{
  json: {
    run_id: run.run_id,
    run_dir: run.run_dir,
    major_task: run.major_task,
    iteration: run.iteration,
    total_tasks: run.plan.tasks.length,
    reviews,
    failure_count: failures.length,
    failures,
    all_passed: failures.length === 0,
    status: failures.length === 0
      ? 'VERIFIED'
      : 'PLAN_REVISION_REQUIRED'
  }
}];

const data = $("Restore Review Data").first().json;

const memory = data.verifier_memory || { reviews: [] };

const entry = {
  run_id: data.run_id,
  iteration: data.iteration,
  task_id: data.task.id,
  verdict: data.review.verdict,
  score: data.review.score,
  problems: data.review.problems || [],
  required_changes: data.review.required_changes || []
};

memory.reviews = [
  ...(memory.reviews || []),
  entry
].slice(-20);

return [{
  json: {
    ...data,
    verifier_memory: memory,
    memory_b64: Buffer
      .from(JSON.stringify(memory, null, 2))
      .toString("base64")
  }
}];
